/** Generated by the virtual project agent only after approval. */
export function providerServerSource(revision, readyDelayMs = 3000, readinessFields = {}) {
  if (!Number.isInteger(revision) || revision < 1 || !Number.isInteger(readyDelayMs) || readyDelayMs < 0) throw new Error("invalid server fixture revision/delay");
  return `import {createServer} from "node:http";
import {writeFile} from "node:fs/promises";
import {quote} from "./service.mjs";
let ready=false; setTimeout(()=>{ready=true},${readyDelayMs});
const revision=${revision};
const server=createServer(async(req,res)=>{
  if(req.url==="/health") {res.writeHead(ready?200:503,{"content-type":"application/json"}).end(JSON.stringify({ready,revision,...${JSON.stringify(readinessFields)}}));return;}
  if(req.method!=="POST"||req.url!=="/quote"){res.writeHead(404).end();return;}
  try {
    let body=""; for await(const chunk of req){body+=chunk;if(body.length>10000)throw new Error("too large");}
    const result=quote(JSON.parse(body));
    res.writeHead(200,{"content-type":"application/json"}).end(JSON.stringify(result));
  } catch(error) {res.writeHead(400,{"content-type":"application/json"}).end(JSON.stringify({error:error.message}));}
});
server.listen(0,"127.0.0.1",async()=>{await writeFile(process.argv[2],JSON.stringify({pid:process.pid,baseUrl:"http://127.0.0.1:"+server.address().port,revision}));});
`;
}
